public class VectorDetector extends Detector implements XmlScanner {
    public static final Issue ISSUE = Issue.create(
            "VectorRaster",
            "Vector Image Generation",
            "Vector icons require API 21 or API 24 depending on used features, ...",
            Category.CORRECTNESS,
            5,
            Severity.WARNING,
            new Implementation(VectorDetector.class, Scope.RESOURCE_FILE_SCOPE));

    private static final String VECTOR_TAG = "vector";
    private static final String CLIP_PATH = "clip-path";
    private static final String ATTR_FILL_TYPE = "fillType";
    private static final String ATTR_FILL_COLOR = "fillColor";
    private static final String ATTR_STROKE_COLOR = "strokeColor";

    @Override
    public Collection<String> getApplicableElements() {
        return XmlScannerConstants.ALL;
    }

    @Override
    public void visitElement(XmlContext context, Element element) {
        String tag = element.getTagName();
        if (CLIP_PATH.equals(tag)) {
            report(context, element, "The `<clip-path>` element is not supported when " +
                    "generating raster images for older devices.");
        }
    }

    @Override
    public Collection<String> getApplicableAttributes() {
        return XmlScannerConstants.ALL;
    }

    @Override
    public void visitAttribute(XmlContext context, Attr attribute) {
        String name = attribute.getLocalName();
        if (ATTR_FILL_TYPE.equals(name)) {
            report(context, attribute, "The `android:fillType` attribute is not supported " +
                    "when generating raster images for older devices.");
        }
    }

    private static void report(XmlContext context, Node node, String message) {
        context.report(ISSUE, node, context.getLocation(node), message);
    }
}
```

