package com.android.tools.lint.checks;

import static com.android.SdkConstants.ATTR_HEIGHT;
import static com.android.SdkConstants.ATTR_WIDTH;
import static com.android.SdkConstants.TAG_CLIP_PATH;
import static com.android.SdkConstants.TAG_VECTOR;

import com.android.resources.ResourceFolderType;
import com.android.tools.lint.detector.api.Category;
import com.android.tools.lint.detector.api.Detector;
import com.android.tools.lint.detector.api.Implementation;
import com.android.tools.lint.detector.api.Issue;
import com.android.tools.lint.detector.api.Scope;
import com.android.tools.lint.detector.api.Severity;
import com.android.tools.lint.detector.api.XmlContext;
import java.util.Arrays;
import java.util.Collection;
import org.w3c.dom.Attr;
import org.w3c.dom.Element;

public class VectorDetector extends Detector implements XmlScanner {
    public static final Issue ISSUE = Issue.create(
            "VectorRaster",
            "Vector Image Generation",
            "Vector icons require API 21 or API 24 ...",
            Category.CORRECTNESS,
            5,
            Severity.WARNING,
            new Implementation(VectorDetector.class, Scope.RESOURCE_FILE_SCOPE));

    private static final String FILL_TYPE = "fillType";

    @Override
    public boolean appliesTo(ResourceFolderType folderType) {
        return folderType == ResourceFolderType.DRAWABLE;
    }

    @Override
    public Collection<String> getApplicableElements() {
        return Arrays.asList(TAG_VECTOR, TAG_CLIP_PATH);
    }

    @Override
    public void visitElement(XmlContext context, Element element) {
        String tag = element.getTagName();
        if (TAG_VECTOR.equals(tag)) {
            // Check size
            checkSize(context, element, ATTR_WIDTH);
            checkSize(context, element, ATTR_HEIGHT);
        } else if (TAG_CLIP_PATH.equals(tag)) {
            context.report(ISSUE, element, context.getLocation(element),
                    "The `<clip-path>` element is not supported when rasterizing vector drawables for older devices");
        }
    }

    @Override
    public Collection<String> getApplicableAttributes() {
        return Arrays.asList(ATTR_WIDTH, ATTR_HEIGHT, FILL_TYPE);
    }

    @Override
    public void visitAttribute(XmlContext context, Attr attribute) {
        String name = attribute.getLocalName();
        if (FILL_TYPE.equals(name)) {
            context.report(ISSUE, attribute, context.getLocation(attribute),
                    "The `android:fillType` attribute is not supported when rasterizing vector drawables for older devices");
        } else if (ATTR_WIDTH.equals(name) || ATTR_HEIGHT.equals(name)) {
            checkSize(context, attribute);
        }
    }

    private static void checkSize(XmlContext context, Element element, String attrName) {
        Attr attr = element.getAttributeNodeNS(ANDROID_URI, attrName);
        if (attr != null) {
            checkSize(context, attr);
        }
    }

    private static void checkSize(XmlContext context, Attr attr) {
        String value = attr.getValue();
        if (value.endsWith("dp")) {
            try {
                int size = Integer.parseInt(value.substring(0, value.length() - 2));
                if (size >= 200) {
                    context.report(ISSUE, attr, context.getLocation(attr),
                            "This vector drawable has a very large width/height. When rasterized for older devices, this can lead to OutOfMemoryErrors. Consider reducing the width/height.");
                }
            } catch (NumberFormatException ignore) {}
        }
    }
}
```

