public class VectorDetector extends Detector implements XmlScanner {
    private static final String TAG_VECTOR = "vector";
    private static final String TAG_CLIP_PATH = "clip-path";
    private static final String TAG_GRADIENT = "gradient";
    private static final String ATTR_FILL_TYPE = "fillType";
    private static final String ATTR_WIDTH = "width";
    private static final String ATTR_HEIGHT = "height";

    public static final Issue ISSUE = Issue.create(
        "VectorRaster",
        "Vector Image Generation",
        "...",
        Category.CORRECTNESS,
        5,
        Severity.WARNING,
        new Implementation(VectorDetector.class, Scope.RESOURCE_FILE_SCOPE));

    @Override
    public boolean appliesTo(ResourceFolderType folderType) { return folderType == ResourceFolderType.DRAWABLE; }

    @Override
    public Collection<String> getApplicableElements() {
        return Arrays.asList(TAG_VECTOR, TAG_CLIP_PATH, TAG_GRADIENT);
    }

    @Override
    public void visitElement(XmlContext context, Element element) {
        if (!isVectorDrawable(context)) return;
        String tag = element.getTagName();
        if (TAG_CLIP_PATH.equals(tag) && context.getProject().getMinSdk() < 24) {
            context.report(ISSUE, element, context.getLocation(element), "The `<clip-path>` element is not supported when rasterizing vector drawables for older devices.");
        } else if (TAG_GRADIENT.equals(tag) && context.getProject().getMinSdk() < 24) {
            context.report(...);
        } else if (TAG_VECTOR.equals(tag) && context.getProject().getMinSdk() < 21) {
            checkSize(...);
        }
    }

    @Override
    public Collection<String> getApplicableAttributes() { return Collections.singletonList(ATTR_FILL_TYPE); }

    @Override
    public void visitAttribute(XmlContext context, Attr attribute) {
        if (!isVectorDrawable(context)) return;
        if (context.getProject().getMinSdk() >= 24) return;
        if (ATTR_FILL_TYPE.equals(attribute.getLocalName())) {
            context.report(...);
        }
    }

    private static boolean isVectorDrawable(XmlContext context) {
        Element root = context.document.getDocumentElement();
        return root != null && TAG_VECTOR.equals(root.getTagName());
    }
}

